self.onmessage=async({data:e})=>{try{importScripts(e.runtime);const t=new Go,n=await fetch(e.wasm,{credentials:"omit"});if(!n.ok)throw new Error("Loupe could not load. Please try again.");const{instance:s}=await WebAssembly.instantiate(await n.arrayBuffer(),t.importObject);t.run(s).catch(()=>self.postMessage({error:"Loupe stopped. Please try another file."}));const o=JSON.parse(self.loupeInspect(new Uint8Array(e.bytes)));self.postMessage(o)}catch{self.postMessage({error:"Loupe could not inspect this file. Reload and try again."})}}